#include "pch.h"
#include "ManagementWindow.xaml.h"
#include "ManagementWindow.g.cpp"
#include "../window/ThemeSync.h"
#include "../input/OwnedFocus.h"
#include <microsoft.ui.xaml.window.h>
namespace winrt::MiniWindow::implementation {
ManagementWindow::ManagementWindow(){InitializeComponent();check_hresult(try_as<IWindowNative>()->get_WindowHandle(&hwnd_));MONITORINFO monitor{sizeof(monitor)};GetMonitorInfoW(MonitorFromWindow(hwnd_,MONITOR_DEFAULTTONEAREST),&monitor);const auto dpi=GetDpiForWindow(hwnd_);AppWindow().Resize({std::min(MulDiv(820,dpi,96),static_cast<int>(monitor.rcWork.right-monitor.rcWork.left)-24),std::min(MulDiv(620,dpi,96),static_cast<int>(monitor.rcWork.bottom-monitor.rcWork.top)-24)});AppWindow().Presenter().as<Microsoft::UI::Windowing::OverlappedPresenter>().IsAlwaysOnTop(true);Navigation().SelectionChanged([this](auto&&,auto const& args){if(!syncing_&&args.SelectedItem()){auto item=args.SelectedItem().as<Microsoft::UI::Xaml::Controls::NavigationViewItem>();Open(static_cast<miniwindow::ManagementPage>(std::stoi(std::wstring(unbox_value<hstring>(item.Tag())))));}});AppWindow().Closing([this](auto&&,Microsoft::UI::Windowing::AppWindowClosingEventArgs const& args){if(!shuttingDown_){args.Cancel(true);if(!pending_)HideAsync();}});}
void ManagementWindow::Bind(HWND owner,miniwindow::AppCoordinator& app,std::function<void()> focus,std::function<bool(UINT,UINT)> capture,std::function<void(miniwindow::HotkeyAction)> beginCapture,std::function<void()> panel){SetLastError(ERROR_SUCCESS);if(!SetWindowLongPtrW(hwnd_,GWLP_HWNDPARENT,reinterpret_cast<LONG_PTR>(owner))&&GetLastError()!=ERROR_SUCCESS)throw_hresult(HRESULT_FROM_WIN32(GetLastError()));app_=&app;bookmarks_=make_self<BookmarkPage>();presets_=make_self<PresetPage>();bookmarks_->Bind(app);presets_->Bind(app);settings_=make_self<SettingsPage>();settings_->Bind(app,std::move(beginCapture),std::move(panel));auto changed=[this,focus](auto&&,auto&&){DispatcherQueue().TryEnqueue([weak=get_weak(),focus]{if(auto self=weak.get();self&&!self->shuttingDown_)focus();});};Root().GotFocus(changed);Root().LostFocus(changed);Root().PreviewKeyDown([capture](auto&&,Microsoft::UI::Xaml::Input::KeyRoutedEventArgs const& args){if(capture(static_cast<UINT>(args.Key()),miniwindow::CurrentKeyModifiers()))args.Handled(true);});SetPage(page_);RefreshTheme();}
void ManagementWindow::SetPage(miniwindow::ManagementPage page){page_=page;syncing_=true;Navigation().SelectedItem(Navigation().MenuItems().GetAt(static_cast<uint32_t>(page)));syncing_=false;if(page==miniwindow::ManagementPage::Bookmarks)PageHost().Content(bookmarks_.as<MiniWindow::BookmarkPage>());else if(page==miniwindow::ManagementPage::Presets)PageHost().Content(presets_.as<MiniWindow::PresetPage>());else PageHost().Content(settings_.as<MiniWindow::SettingsPage>());Refresh();}
void ManagementWindow::Open(miniwindow::ManagementPage page){if(shuttingDown_||!app_)return;Activate();if(page!=page_&&!pending_)NavigateAsync(page);else Refresh();}
void ManagementWindow::Refresh(){if(!app_)return;bookmarks_->Refresh();presets_->Refresh();settings_->Refresh();RefreshTheme();}
void ManagementWindow::RefreshTheme(){if(app_)miniwindow::ThemeSync::Apply(hwnd_,app_->Snapshot().state.settings.themeMode,Root(),AppWindow());}
bool ManagementWindow::Dirty(){return app_&&((page_==miniwindow::ManagementPage::Bookmarks&&bookmarks_->Dirty())||(page_==miniwindow::ManagementPage::Presets&&presets_->Dirty())||(page_==miniwindow::ManagementPage::Settings&&settings_->Dirty()));}
bool ManagementWindow::ForegroundTextFocus(){return GetAncestor(GetForegroundWindow(),GA_ROOT)==hwnd_&&miniwindow::HasOwnedTextFocus(Root().XamlRoot());}
Windows::Foundation::IAsyncOperation<bool> ManagementWindow::CanLeaveAsync(){auto lifetime=get_strong();if(Dirty())Activate();if(page_==miniwindow::ManagementPage::Bookmarks)co_return co_await bookmarks_->CanLeaveAsync();if(page_==miniwindow::ManagementPage::Presets)co_return co_await presets_->CanLeaveAsync();if(page_==miniwindow::ManagementPage::Settings)co_return co_await settings_->CanLeaveAsync();co_return true;}
Windows::Foundation::IAsyncAction ManagementWindow::NavigateAsync(miniwindow::ManagementPage page){auto lifetime=get_strong();pending_=true;syncing_=true;Navigation().SelectedItem(Navigation().MenuItems().GetAt(static_cast<uint32_t>(page_)));syncing_=false;try{if(co_await CanLeaveAsync())SetPage(page);}catch(const hresult_error&){}pending_=false;}
Windows::Foundation::IAsyncAction ManagementWindow::HideAsync(){auto lifetime=get_strong();pending_=true;try{if(co_await CanLeaveAsync()){ShowWindow(hwnd_,SW_HIDE);}}catch(const hresult_error&){}pending_=false;}
void ManagementWindow::Shutdown(){shuttingDown_=true;Close();}
}
